P=pathlib.Path(__file__).parent
fields='paper_id title authors year venue doi_or_arxiv official_url version source_verified full_text_access discussion_access domain axis_tags original_rq dataset stimulus brain_measurement model_method training_objective main_findings scientific_contribution limitations future_directions future_direction_source_location transfer_idea relevant_datasets novelty_risk evidence_level agent verification_date source needs_followup'.split()
