def add(id,title,authors,year,venue,arxiv,repo,source,domain,axes,rq,data,stim,brain,method,obj,finding,contrib,lim,transfer,novelty,**kw):
 row=dict(zip(fields,['']*len(fields)))
 row.update(paper_id=id,title=title,authors=authors,year=year,venue=venue,doi_or_arxiv=arxiv,official_url=repo,version='2026-11-12 공식 저장소 스냅샷; 논문 버전 번호 미확인',source_verified='공식 저장소의 서지 및 구현 설명 직접 확인; 논문 본문 미확인',full_text_access='아니오; 공식 README/코드만 확인',discussion_access='아니오',domain=domain,axis_tags=axes,original_rq=rq,dataset=data,stimulus=stim,brain_measurement=brain,model_method=method,training_objective=obj,main_findings=finding,scientific_contribution=contrib,limitations=lim,future_directions='저자 Discussion 미열람으로 직접 제안 미확인; Agent 전이는 transfer_idea에 E3로 분리',future_direction_source_location='미확인',transfer_idea='E3: '+transfer,relevant_datasets='Horikawa; Emo-FilM; Spacetop; NSD — 현 단계 조건부 후보이며 실제 적합성은 데이터 감사 후 결정',novelty_risk=novelty,evidence_level='E1(공식 README/코드 범위; 논문 결과 검증과 구분)',agent='04_brain_foundation',verification_date='2026-11-12',source=source,needs_followup='논문 본문·Discussion 및 체크포인트 다운로드/실행 확인; 모델카드 참조')
 row.update(kw);rows.append(row)
add('BF01','SwiFT: Swin 4D fMRI Transformer','Peter Kim; Junbeom Kwon; Sunghwan Joo; Sangyoon Bae; Donggyu Lee; Yoonho Jung; Shinjae Yoo; Jiook Cha; Taesup Moon',2023,'Advances in Neural Information Processing Systems 36:42015–42037','arXiv:2307.05916','https://github.com/Transconnectome/SwiFT','sources/swift.txt; sources/swift_tail.txt; sources/swift_pretrained_tree.txt','fMRI 표현학습','F;I;J;O;Q;S','4차원 fMRI를 직접 처리하면서 확장 가능한 개인별 표형 예측을 할 수 있는가?','HCP; ABCD; UKB(공식 contrastive checkpoint 설명)','fMRI 자체; 자극 인코더 아님','MNI 정렬 4D fMRI','4D shifted-window Swin Transformer; 분류/회귀 head','instance 및 local-local temporal contrastive 옵션; 감독학습','공식 구현은 4D 처리·자기지도 손실·공개 checkpoint 파일 경로를 제공한다. 본문 성능표는 미확인.','E3 해석: ROI 평균을 먼저 가정하지 않는 공간·시간 표현 비교가 가능하다.','README의 전처리 및 움직임 영향 검토 문구 확인; 원문 한계 미확인. 고정 입력과 pooling 영향은 Agent의 방법론적 우려.','공간 입력과 시간 순서 보존 정도를 바꾸어 정서 관련 신호의 소실 지점을 비교한다.','새 분류기 적용만으로 신규성 없음; 정보 보존에 대한 경쟁 가설이 필요')
add('BF02','Scaling Vision Transformers for Functional MRI with Flat Maps','Connor Lane; Mihir Tripathy; Leema Krishna Murali; Ratna Sagari Grandhi; Shamus Sim Zi Yang; Sam Gijsen; Debojyoti Das; Manish Ram; Utkarsh Kumar Singh; Cesar Kadir Torrico Villanueva; Yuxiang Wei; Will Beddow; Gianfranco Cortés; Suin Cho; Daniel Z. Kaplan; Benjamin Warner; Tanishq Mathew Abraham; Paul S. Scotti',2026,'ICML (공식 README 인용 기준)','arXiv:2510.13768','https://github.com/MedARC-AI/CortexMAE','sources/cortexmae.md; sources/cortex_config.txt; sources/cortex_inference.txt; sources/brainmarks.txt','fMRI 파운데이션 모델','F;I;J;Q;T','fMRI 공간 표현을 바꾸면 ViT 사전학습의 확장성과 이전 가능한 정보가 어떻게 달라지는가?','HCP-YA 2.1K시간(README); Brainmarks 평가','fMRI 자체','parcel; 피질 flat map; cortex-only MNI volume','CortexMAE-P/F/V; ViT-B MAE; Brainmarks','기본 설정 90% tube masking과 재구성','공식 README는 세 입력 공간 및 50개 이상 ablation 모델 링크를 제공한다. 기본 16frame·시간patch4·target TR1s는 코드에서 확인. 본문 비교 성능은 미확인.','E3 해석: 동일 계열에서 공간 표현과 정보 손실을 비교할 도구.','기본 세 모델이 피질 중심이라는 구현 제약; 입력을1초로 재표본화해도 관측 해상도가 향상되지 않음(Agent 추론).','parcel 평균으로 사라진 정서 관련 잔여정보가 dense cortex 표현에서 보존되는지 동일 데이터·probe 조건에서 비교한다.','공간 해상도 증가 자체는 신규성 아님; 제거된 신호의 구조와 경쟁 설명을 검증해야 함')
add('BF03','A foundation model of vision, audition, and language for in-silico neuroscience',"Stéphane d’Ascoli; Jérémy Rapin; Yohann Benchetrit; Teon Brooks; Katelyn Begany; Joséphine Raugel; Hubert Banville; Jean-Rémi King",2026,'arXiv preprint','arXiv:2605.04326','https://github.com/facebookresearch/tribev2','sources/tribev2.md; sources/tribe_config.txt; sources/tribe_model.txt; sources/tribe_demo.txt','멀티모달 뇌 인코딩','H;I;M;O;P;Q','시각·청각·언어 자극에서 통합 모델로 뇌반응을 예측하고 계산 실험을 할 수 있는가?','기본 코드: Algonauts2025Bold; Wen2017; Lahner2024Bold; Lebel2023Bold. 전체 논문 학습 corpus와의 일치 미확인','video; audio; text','fsaverage5 피질 fMRI 반응; 공개 추론 기본은 평균 피험자','Llama-3.2-3B; V-JEPA2; Wav2VecBert 특성 + Transformer; subject head','기본 코드 MSELoss; modality dropout0.3; subject dropout0.1','공식 API가 자극에서 시간×피질vertex 출력을 제공하고 5초 offset을 명시. 실제 예측 정확도 및 일반화 범위는 본문 미확인.','E3 해석: 외부 자극 조건부 예측과 실제 신경변동의 차이를 명시적으로 검사할 수 있다.','평균 피험자 출력은 개인별 진실이 아님; 모형 잔차에는 HRF·신호품질·정렬오차가 섞일 수 있음(Agent 추론).','자극 인코더의 교차검증 잔차를 fMRI 표현모델의 조건부 예측과 대조해 자극으로 설명되지 않는 재현 가능한 정보를 찾는다.','모형 잔차를 곧바로 정서 고유 성분으로 명명하면 오류; 외부 자극·시간·신호품질 통제 필요')
add('BF04','Brain-Mamba: Encoding Brain Activity via Selective State Space Models','Ali Behrouz; Farnoosh Hashemi',2024,'Conference on Health, Inference, and Learning; PMLR248:233–250','PMLR:behrouz24a','https://proceedings.mlr.press/v248/behrouz24a.html','sources/brainmamba_pmlr.txt; sources/brainmamba_full.pdf; sources/brainmamba_full_text.txt','신경 시계열·그래프 표현학습','F;I;J;N;S;T','서로 다른 공간·시간 해상도의 신경신호에서 장거리 의존성을 효율적으로 학습할 수 있는가?','BVFC; BVFC-MEG; ADHD; TUH-EEG; MPI-EEG; HCP-Mental; HCP-Age(논문명칭)','영상 시각자극; HCP task; 휴지기 및 임상 신호','fMRI; MEG; EEG','BTMamba 시계열 + BNMamba 그래프; functional ordering; 입력의존 selective SSM; gate','두 encoder 상호정보량 최대화 사전학습; 분류/이상탐지','Table2 BVFC 75.19±1.98%, BVFC-MEG78.03±1.69% ACC 보고. Fig2–3 시간/메모리 scaling, Fig4 합성 corruption 실험. 이는 미수행한 외부 OOD 검증을 대신하지 않는다.','공간·시간 두 해석에서 공통 정보를 학습하면서 선택적 scan으로 복잡도를 줄임.','AppendixE: Pearson 연결망 고정, 피험자 동일 취급, 분포이동 평가 미수행. AppendixD 무작위70/10/20 분할만 명시하며 subject/stimulus 독립성 상세 부족.','시간적 상태 선택이 자극 사건의 예측오차와 관련된 뇌반응을 보존하는지 정적SSM·순서교란·HRF대조와 비교한다.','상태공간모델이 뇌의 실제 메커니즘이라는 주장은 불가; 최신 Mamba로 대체만 해서는 신규성 없음',version='PMLR 최종 공개 PDF, pp233–250',source_verified='출판사 공식 저장소 서지 및 출판사 PDF 본문·부록 직접 확인',full_text_access='예; 출판사 PDF 전체',discussion_access='예; Conclusion p242 및 Appendix E pp249–250',evidence_level='E1(논문 본문·부록 직접 확인)',future_directions='저자 명시: 다른 임상조건; Pearson 고정 연결망을 학습형으로 대체; 피험자별 신호품질을 고려한 강건 학습; 다중모달 확장; 분포이동 강건성 평가',future_direction_source_location='Appendix E: Limitations & Future Work, pp249–250',needs_followup='논문 공식 software 링크 GraphMamba/BrainMamba가404; 공식 코드/가중치/라이선스 복구 여부 및 subject·stimulus 분할 상세 확인')
add('BF05','Brain-JEPA: Brain Dynamics Foundation Model with Gradient Positioning and Spatiotemporal Masking','Zijian Dong; Ruilin Li; Yilei Wu; Thuan Tinh Nguyen; Joanna Su Xian Chong; Fang Ji; Nathanael Ren Jie Tong; Christopher Li Hsian Chen; Juan Helen Zhou',2024,'NeurIPS 2024 Spotlight (공식 README)','arXiv:2409.19407','https://github.com/Eric-LRL/Brain-JEPA','sources/brainjepa.md; sources/jepa_config.txt','fMRI 자기지도학습','D;F;I;J;K','신호의 원값 대신 예측 가능한 잠재표현을 학습하여 뇌동역학 표현을 얻을 수 있는가?','UKB; HCP-Aging; ADNI; MACC. README는 pretrain과 평가 상세 규모를 분리 제시하지 않음','fMRI 자체','400 Schaefer +50 Tian subcortical ROI','JEPA; gradient positioning; Cross-ROI/Cross-Time/Double-Cross masking','한 observation block에서 target block latent 예측','공식 구현 및450×160 입력 예시,4A10040GB사전학습 보고,checkpoint 링크 확인. 성능표 미확인.','E3 해석: 원신호 보존과 예측 가능한 잠재정보 보존의 차이를 시험할 수 있다.','ROI 평균 및 population gradient 편향 가능성은 Agent 추론; representation-conditioned reconstruction 코드는 README TODO로 미공개 표시.','MAE와 JEPA의 정보 손실을 같은 ROI와probe조건에서 비교해 정서 관련 성분이 예측 가능한 구조인지 단기 변동인지 구별한다.','JEPA 채택 자체는 이미 이루어짐; 특정 신호 손실의 반증 가능한 검증이 필요')
add('BF06','Brain Harmony: A Multimodal Foundation Model Unifying Morphology and Function into 1D Tokens','Zijian Dong; Ruilin Li; Joanna Su Xian Chong; Niousha Dehestani; Yinghui Teng; Yi Lin; Zhizhou Li; Yichi Zhang; Yapei Xie; Leon Qi Rong Ooi; others (공식 README 축약 인용)',2025,'NeurIPS 2025 (공식 README)','arXiv:2509.24693','https://github.com/hzlab/Brain-Harmony','sources/brainharmony.md; sources/harmony_config.txt','구조·기능 통합 뇌 표현','F;I;J;M;O;X','형태와 기능을 공통 1D token 체계로 통합할 수 있는가?','공개 stage0 설정 UKB_fusion; 전체 학습집합은 본문 미확인','자극 인코더 아님; T1 및 fMRI','구조 MRI와400ROI fMRI','BrainHarmonix; modality encoder + harmonizer','README 자기지도 사전학습; 세부 전체 손실 미확인','fMRI·T1·joint pretrained checkpoint 링크 및3단계 파이프라인 확인. 현재 본문 성능표 미확인.','E3 해석: 기능표현에 구조정보를 조건화한 모형과 기능전용 모형을 비교할 도구.','구조가 부가 정보인지 신원·site 단서인지 구별 필요(Agent 추론); 전체 저자명·학습량 미확인.','형태 정보를 조건화한 후에도 재현 가능한 정서 관련 기능표상 차이가 남는지 기능전용·구조shuffle대조와 비교한다.','개인차 예측 향상만으로 계산적 설명 성립하지 않음')
add('BF07','Pre-training and Fine-tuning Transformers for fMRI Prediction Tasks','Itzik Malkiel; Gony Rosenman; Lior Wolf; Talma Hendler',2021,'arXiv preprint (읽은 공식 README 인용 기준)','arXiv:2112.05761','https://github.com/GonyRosenman/TFF','sources/tff.txt; sources/tff_model.txt','fMRI 사전학습 초기기술','F;I;J;T','3D fMRI 공간정보와 시간 Transformer를 결합한 사전학습이 예측에 유용한가?','HCP S1200; UCLA LA5c','휴지기 fMRI','4D volumetric fMRI','3D CNN encoder/decoder; Transformer; downstream head','코드에 autoencoder_reconstruction 및 transformer_reconstruction 구현','공식 코드에 재구성·분류·회귀 구현이 존재. 정확한 하이퍼파라미터를 추후 추가한다는 README 문구 유지; 결과는 미확인.','E3 해석: 최신 뇌모형 이전에 존재한 재구성·시간변환 baseline 제공.','공식 README HyperParameters 절에 정확한 설정 공개가 미래형으로 남음; 가중치·license 미확인.','동일입력의 단순 공간encoder+시간Transformer를 강한 baseline으로 두어 파운데이션 특이 효과를 판별한다.','재구성기반 전이 자체는 오래된 접근; 비교 baseline 용도')
add('BF08','Masked Autoencoders Are Scalable Vision Learners',"Kaiming He; Xinlei Chen; Saining Xie; Yanghao Li; Piotr Dollár; Ross Girshick",2021,'arXiv preprint (공식 저장소 인용 기준)','arXiv:2111.06377','https://github.com/facebookresearch/mae','sources/mae.txt','시각 자기지도학습의 원 계산원리','I;J;T','대부분 가린 이미지의 복원이 확장 가능한 표현학습 목표가 될 수 있는가?','ImageNet-1K; 전이평가 데이터들(README)','정적 이미지','해당없음','ViT encoder + masked reconstruction decoder','masked patch reconstruction','공식 PyTorch 재구현 및 TF/TPU에서 변환한 ViT-B/L/H 가중치 링크 확인. README 성능표는 존재하나 논문본문 미확인.','E3 해석: 마스킹의 단위가 요구하는 통계적 지식을 규정한다는 전이 원리.','이미지 사전학습이 fMRI 신경메커니즘을 보장하지 않음(Agent 추론).','공간tube·시간block·무작위mask를 비교하여 정서 관련 신경정보가 어느 조건부 예측 문제에서 보존되는지 검사한다.','MAE의 fMRI 적용은 이미 존재; mask 목표가 서로 다른 신경가설을 구별해야 함')
add('BF09','Self-Supervised Learning from Images with a Joint-Embedding Predictive Architecture','Mahmoud Assran; Quentin Duval; Ishan Misra; Piotr Bojanowski; Pascal Vincent; Michael Rabbat; Yann LeCun; Nicolas Ballas',2023,'CVPR2023 (공식 README)','arXiv:2301.08243','https://github.com/facebookresearch/ijepa','sources/ijepa.txt','시각 잠재공간 예측','I;J;V;X','픽셀 복원이나 수작업 변환 불변성 없이 이미지 일부에서 다른 부분의 표현을 예측할 수 있는가?','ImageNet-1K; ImageNet-22K','정적 이미지','해당없음','context encoder; target encoder; latent predictor','target representation prediction','공식 설명은 pixel 대신 latent를 예측하며 손으로 지정한 view augmentation을 요구하지 않는다고 명시. 학습 코드 및 checkpoint 링크 확인.','E3 해석: 관측의 세부 복제와 예측 가능한 추상 정보의 분리를 비교할 수 있다.','정적 이미지의 부분 예측을 실제 시간적 world model과 동일시할 수 없음(Agent 추론).','원신호 복원형과 잠재예측형이 보존하는 정서 관련 뇌정보를 분해한다.','Brain-JEPA가 이미 전이했으므로 단순 차용은 중복')
add('BF10','Mamba: Linear-Time Sequence Modeling with Selective State Spaces','Albert Gu; Tri Dao',2023,'arXiv preprint (공식 README 인용 기준)','arXiv:2312.00752','https://github.com/state-spaces/mamba','sources/mamba.txt; sources/mamba_license.txt','입력의존 상태공간 순차모형','D;I;N;V','입력에 따라 보존할 상태를 선택하면서 긴 순서를 효율적으로 처리할 수 있는가?','Pile300B token; SlimPajama600B token 모델(공식 README)','텍스트 sequence; 원방법은 일반 sequence block','해당없음','selective SSM; hardware-aware scan','공식 언어모델 예제; 구체 논문 학습손실 본문 미확인','공식 selective scan 및 sequence block 코드와언어모델가중치 링크 확인; 후속Mamba2/3도 같은 저장소에서 별도논문으로 제공.','E3 해석: 고정 시간상수 대신 입력의존 상태 갱신을 경쟁 계산모형으로 제시.','Mamba 언어 가중치를 Brain-Mamba checkpoint로 혼동할 수 없음; SSM recurrent dynamics 정밀도 민감성은 README Troubleshooting에 명시.','입력의존 선택이 사건경계에서 필요한 정보의 유지·소실을 설명하는지 비선택SSM과 비교한다.','Brain-Mamba가 이미 SSM 적용; 신경학적 식별성과 장기맥락가설이 신규성 기준')
with (P/'papers.csv').open('w',newline='',encoding='utf-8-sig') as f:
 w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(rows)
# 다운로드 기록은 실패와 성공을 모두 남기며, 성공 파일에 바이트 해시를 붙인다.
log=json.loads((P/'sources/access_log.json').read_text());manifest=[]
for r in log:
 n,u,status,*tail=r
 candidates=[P/'sources'/f'{n}{ext}' for ext in ['.pdf','.md','.txt','.html']]
 path=next((f for f in candidates if f.exists()),None)
 manifest.append(dict(source_id=n,url=u,status=status,local_file=str(path.relative_to(P)) if path else '',sha256=hashlib.sha256(path.read_bytes()).hexdigest() if path else '',verified_on='2026-11-12',origin_agent='04_brain_foundation'))
with (P/'source_manifest.csv').open('w',newline='',encoding='utf-8-sig') as f:
 w=csv.DictWriter(f,fieldnames=['source_id','url','status','local_file','sha256','verified_on','origin_agent']);w.writeheader();w.writerows(manifest)
commits={}
for p in (P/'sources').glob('*'):
 if p.suffix in ['.html','.txt']:
  text=p.read_text(errors='replace');m=re.search('"currentOid":"([a-f0-9]{40})"',text)
  if m:commits[p.name]=m.group(1)
(P/'sources/observed_commits.json').write_text(json.dumps(commits,ensure_ascii=False,indent=2))
print('문헌',len(rows),'열',len(fields),'출처접근기록',len(manifest),'관측commit',len(commits))
